#

locals {
  secret_files_path           = try(var.secret_files.files_path, "")
  secret_config_path          = local.secret_files_path != "" ? format("%s/%s", local.values_path, local.secret_files_path) : local.values_path
  secret_files_in_config_path = try(var.secret_files.enabled, false) == true ? fileset(local.secret_config_path, "*") : []
  secret_index                = local.configmap_enabled ? 1 : 0
  secret_enabled              = try(var.secret_files.mount_point, "") != "" && try(var.secret_files.enabled, false) == true
  secret_mount_overrides = local.secret_enabled ? zipmap(
    [
      "injectedVolumes[${local.secret_index}].name",
      "injectedVolumes[${local.secret_index}].secret.secretName",
      "injectedVolumeMounts[${local.secret_index}].name",
      "injectedVolumeMounts[${local.secret_index}].mountPath",
    ],
    [
      "${var.release.name}-injected-secret-files",
      "${var.release.name}-injected-secret-files",
      "${var.release.name}-injected-secret-files",
      var.secret_files.mount_point,
    ]
  ) : {}
}

resource "kubernetes_secret" "secret_files" {
  count = try(var.secret_files.enabled, false) == true && length(local.secret_files_in_config_path) > 0 ? 1 : 0
  metadata {
    name      = "${var.release.name}-injected-secret-files"
    namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata.0.name : data.kubernetes_namespace.this[0].metadata.0.name
    labels = {
      "app.kubernetes.io/name"       = var.release.name
      "app.kubernetes.io/version"    = local.release_version
      "app.kubernetes.io/managed-by" = "Terraform"
    }
  }
  data = {
    for file in local.secret_files_in_config_path : file => templatefile("${local.secret_config_path}/${file}", local.all_secrets_map)
    if !contains([".empty", ".placeholder"], file)
  }
}

##
# (c) 2021-2025
#     Cloud Ops Works LLC - https://cloudops.works/
#     Find us on:
#       GitHub: https://github.com/cloudopsworks
#       WebSite: https://cloudops.works
#     Distributed Under Apache v2.0 License
#

data "aws_secretsmanager_secrets" "secrets" {
  for_each = toset(local.secrets_path_filter)
  filter {
    name   = "name"
    values = [each.value]
  }
}

locals {
  secrets_map_pre = merge([
    for prefix in toset(local.secrets_path_filter) : {
      for secret_name in data.aws_secretsmanager_secrets.secrets[prefix].names : secret_name => {
        secret_name  = secret_name
        prefix       = prefix
        filtered_key = replace(replace(secret_name, "/", "|"), replace(format("%s", prefix), "/", "|"), "")
        splitted_key = split("/", secret_name)
      }
    }
  ]...)

  secrets_map = {
    for key, value in local.secrets_map_pre : key => {
      secret_name  = value.secret_name
      prefix       = value.prefix
      filtered_key = replace(replace((value.filtered_key != "" ? value.filtered_key : value.splitted_key[(length(value.splitted_key) - 1)]), "-", "_"), "/^[-_|]+/", "")
    }
  }

  secrets_plain = {
    for key, value in local.secrets_map : value.filtered_key => data.aws_secretsmanager_secret_version.secret[key].secret_string
    if !startswith(data.aws_secretsmanager_secret_version.secret[key].secret_string, "{")
  }

  secrets_json = merge([
    for key, secret in local.secrets_map : {
      for ent, value in tomap(jsondecode(data.aws_secretsmanager_secret_version.secret[key].secret_string)) :
      "${lower(secret.filtered_key)}_${lower(ent)}" => value
    }
    if startswith(data.aws_secretsmanager_secret_version.secret[key].secret_string, "{")
  ]...)

  all_secrets_map = merge(local.secrets_plain, local.secrets_json)
}

data "aws_secretsmanager_secret_version" "secret" {
  for_each  = local.secrets_map
  secret_id = each.value.secret_name
}

resource "kubernetes_secret" "secrets" {
  count = length(local.secrets_path_filter) > 0 && !local.external_secrets_enabled ? 1 : 0
  metadata {
    name      = "${var.release.name}-injected-secrets"
    namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata.0.name : data.kubernetes_namespace.this[0].metadata.0.name
  }
  data = local.all_secrets_map
}

##
# (c) 2021-2025
#     Cloud Ops Works LLC - https://cloudops.works/
#     Find us on:
#       GitHub: https://github.com/cloudopsworks
